"""Sinh GNU ld linker script (GCC arm-none-eabi) từ model.Device.

Chọn 1 vùng flash (kind=='flash', địa chỉ thấp nhất) và 1 vùng ram để app dùng
(ưu tiên region có tên chứa "USR" - theo quy ước FU2.yaml RAM_SYS/RAM_USR;
nếu không có thì lấy vùng ram đầu tiên). Vùng RAM còn lại (vd RAM_SYS) không bị
đụng tới bởi linker script này - để dành cho firmware hệ thống/DMA buffer khác.
"""

TEMPLATE = """/*
 * Auto-generated by mcu-description/tools/generate.py - DO NOT EDIT BY HAND.
 * Source: mcu-description/devices/{device}.yaml
 * Regenerate: python3 mcu-description/tools/generate.py --device {device}
 */

ENTRY(Reset_Handler)

_Min_Heap_Size  = 0x400;  /* required amount of heap  */
_Min_Stack_Size = 0x400;  /* required amount of stack */

MEMORY
{{
  FLASH (rx)  : ORIGIN = 0x{flash_addr:08X}, LENGTH = 0x{flash_size:X}
  RAM   (rwx) : ORIGIN = 0x{ram_addr:08X}, LENGTH = 0x{ram_size:X}
}}

_estack = ORIGIN(RAM) + LENGTH(RAM);

SECTIONS
{{
  .isr_vector :
  {{
    . = ALIGN(4);
    KEEP(*(.isr_vector))
    . = ALIGN(4);
  }} > FLASH

  .text :
  {{
    . = ALIGN(4);
    *(.text)
    *(.text*)
    *(.glue_7)
    *(.glue_7t)
    KEEP (*(.init))
    KEEP (*(.fini))
    . = ALIGN(4);
    _etext = .;
  }} > FLASH

  .rodata :
  {{
    . = ALIGN(4);
    *(.rodata)
    *(.rodata*)
    . = ALIGN(4);
  }} > FLASH

  .ARM.extab : {{ *(.ARM.extab* .gnu.linkonce.armextab.*) }} > FLASH
  .ARM.exidx :
  {{
    __exidx_start = .;
    *(.ARM.exidx*)
    __exidx_end = .;
  }} > FLASH

  _sidata = LOADADDR(.data);

  .data :
  {{
    . = ALIGN(4);
    _sdata = .;
    /* Hàm thao tác Flash phải chạy từ RAM để không fetch instruction từ
       chính mảng Flash trong lúc controller đang program/erase. */
    *(.ramfunc)
    *(.ramfunc*)
    *(.data)
    *(.data*)
    . = ALIGN(4);
    _edata = .;
  }} > RAM AT> FLASH

  . = ALIGN(4);
  .bss :
  {{
    _sbss = .;
    *(.bss)
    *(.bss*)
    *(COMMON)
    . = ALIGN(4);
    _ebss = .;
  }} > RAM

  ._user_heap_stack :
  {{
    . = ALIGN(8);
    PROVIDE ( end = . );
    PROVIDE ( _end = . );
    . = . + _Min_Heap_Size;
    . = . + _Min_Stack_Size;
    . = ALIGN(8);
  }} > RAM

  /DISCARD/ : {{ libc.a ( * ) libm.a ( * ) libgcc.a ( * ) }}
}}
"""


from mcu_desc.memory_layout import image_layout, profile_ranges, pick_flash as _pick_flash, pick_ram as _pick_ram


def _write_script(device, image, out_path):
    layout = image_layout(device, image)
    content = TEMPLATE.format(
        device=device.device,
        flash_addr=layout.flash_base, flash_size=layout.flash_size,
        ram_addr=layout.ram_base, ram_size=layout.ram_size,
    )
    if device.profile.flash:
        content = content.replace(
            f"--device {device.device}\n",
            f"--device {device.device} --profile {device.profile.name}\n",
        )
    regions, symbols, sections, assertions = [], [], [], []
    # ROM owns the image header and IRQ relay. Their reservations only affect
    # application origins/sizes; do not emit linker regions, sections, or symbols.
    for kind, entry, base in profile_ranges(device):
        if entry.name in ("application", "image_header", "irq_relay"):
            continue
        name = f"PROFILE_{kind.upper()}_{entry.name.upper()}"
        # No automatic section matching: additional ranges require explicit
        # placement. Default code/data/heap/stack use only application ranges.
        regions.append(f"  {name} : ORIGIN = 0x{base:08X}, LENGTH = 0x{entry.size:X} /* {entry.usage} */")
        symbol = f"__profile_{kind}_{entry.name}"
        symbols.extend([
            f"{symbol}_start__ = ORIGIN({name});",
            f"{symbol}_end__ = ORIGIN({name}) + LENGTH({name});",
            f"{symbol}_size__ = LENGTH({name});",
        ])
        if entry.usage == "reserved":
            sections.append(f"""  .reserved_{kind}_{entry.name} (NOLOAD) :
  {{
    . = ORIGIN({name}) + LENGTH({name});
  }} > {name}
""")
    if device.profile.flash:
        symbols.append("__vector_table_start__ = ORIGIN(FLASH);")
        assertions.append('  ASSERT(ADDR(.isr_vector) == ORIGIN(FLASH), "vector table moved from configured base")')
        if regions:
            content = content.replace("MEMORY\n{\n", "MEMORY\n{\n" + "\n".join(regions) + "\n")
        content = content.replace("_estack =", "\n".join(symbols) + "\n_estack =")
        if sections:
            content = content.replace("SECTIONS\n{\n", "SECTIONS\n{\n" + "\n".join(sections) + "\n")
        content = content.replace("  /DISCARD/", "\n".join(assertions) + "\n  /DISCARD/")
    with open(out_path, "w", encoding="utf-8") as f:
        f.write(content)


def generate(device, out_path: str):
    """Generate the selected profile's standalone image."""
    _write_script(device, "standalone", out_path)


def generate_bootloader_partitions(device, bootloader_out_path: str, app_out_path: str):
    """Generate bootloader and app using the same selected memory profile."""
    _write_script(device, "bootloader", bootloader_out_path)
    _write_script(device, "app", app_out_path)
